import re as _re
_NOUNS = [('dollar','dolar'),('peso','peso'),('pound','funt'),('franc','frank'),('dinar','dinar'),('riyal','rial'),('rial','rial'),('rupee','rupia'),('shilling','szyling'),('kwacha','kwacha'),('krona','korona'),('krone','korona'),('ruble','rubel')]


def lang(x):
    return LANG.get(x, x)


def cur(x):
    if x in CUR:
        return CUR[x]
    for e, p in _NOUNS:
        if _re.search(r'\b' + e + r'\b', x):
            return p
    return x.split()[-1]
